#include <string>
#include <vector>

int main() {
    std::vector<int> lecturas{-4, 0, 7, 10, -5};
    int validas{0};
    int rechazadas{0};
    int suma{0};
    for (int lectura : lecturas) {
        std::cout << "Dato=" << lectura << ":";
        if (lectura < -4 || lectura > 9) {
            ++rechazadas;
            std::cout << "Fuera\n";
        } else {
            ++validas;
            suma += lectura;
            if (lectura < 0) {
                std::cout << "Fria\n";
            } else if (lectura == 0) {
                std::cout << "Neutra\n";
            } else {
                std::cout << "Calida\n";
            }
        }
    }
    std::cout << "Resumen=" << validas << ":" << rechazadas << ":" << suma;
    return 0;
}

