    return "Calida";
}

void procesar(const std::vector<int>& lecturas) {
    int validas{0};
    int rechazadas{0};
    int suma{0};
    for (int lectura : lecturas) {
        std::cout << "Dato=" << lectura << ":";
        if (lectura < -4 || lectura > 9) {
            ++rechazadas;
            std::cout << "Fuera\n";
        } else {
            ++validas;
            suma += lectura;
            std::cout << etiqueta_de_lectura(lectura) << "\n";
        }
    }
    std::cout << "Resumen=" << validas << ":" << rechazadas << ":" << suma << "\n";
}

int main() {
    procesar({-4, 0, 7, 10, -5});
    procesar({});
    procesar({-5, -4, -3});
    procesar({8, 9, 10});
    procesar({-1, 0, 1});
    procesar({-5, 10});
    procesar({9, 9, -4, 0});
    return 0;
}

